-- Warrior RP original speech and emote catalog (deDE)
local _, addon = ...
addon.localeData.deDE.texts = {
    HEROIC_STRIKE = { name = "Heldenhafter Stoß", ziel = { "%s, das war meine höfliche Einleitung.", "*nimmt %s ins Auge und lässt die Waffe aus einer überraschend kurzen Bewegung niedersausen.*" }, gruppe = { "Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Es gibt Argumente, die brauchen keinen zweiten Satz.", "*schiebt die Schulter nach und lässt den Stahl sprechen.*" } },
    CHARGE = { name = "Sturmangriff", ziel = { "%s, fangt mich bloß nicht auf!", "*setzt geradewegs auf %s zu und überbrückt die letzten Schritte im Sturm.*" }, gruppe = { "Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" } },
    REND = { name = "Verwunden", ziel = { "%s, Eure Rüstung lässt eine Frage offen.", "*setzt bei %s einen kurzen Schnitt zwischen zwei Platten.*" }, gruppe = { "Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" } },
    HAMSTRING = { name = "Kniesehne", ziel = { "%s, unser Gespräch wird im Stehen fortgesetzt.", "*geht seitlich an %s vorbei und führt einen tiefen, kontrollierten Hieb.*" }, gruppe = { "Weglaufen? Das ist ein Plan mit Schwächen.", "*taucht tief unter der gegnerischen Deckung hindurch.*", "Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" } },
    THUNDER_CLAP = { name = "Donnerknall", ziel = {  }, gruppe = { "Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Hört Ihr das? Die Erde erhebt Einspruch.", "*reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" } },
    CLEAVE = { name = "Spalten", ziel = {  }, gruppe = { "Wer nebeneinander antritt, teilt sich auch die Probleme.", "*schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" } },
    EXECUTE = { name = "Hinrichten", ziel = { "%s, für Euch endet die Diskussion hier.", "*fixiert %s für einen einzigen ruhigen Atemzug, dann fällt die Klinge.*" }, gruppe = { "Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Jetzt wird nicht mehr verhandelt.", "*fasst den Griff fester und schließt die letzte Lücke.*" } },
    SUNDER_ARMOR = { name = "Rüstung zerreißen", ziel = { "%s, Euer Schmied wird Fragen haben.", "*prüft bei %s die Fuge zwischen zwei Platten mit einem harten Schlag.*" }, gruppe = { "Schöner Harnisch. Schade um die Nieten.", "*setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Teurer Stahl ist noch keine gute Deckung.", "*zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" } },
    SHIELD_BLOCK = { name = "Schildblock", ziel = {  }, gruppe = { "Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Ein gutes Schild hört zu, bevor es antwortet.", "*stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" } },
    SHIELD_BASH = { name = "Schildhieb", ziel = { "%s, spart Euch die nächste Silbe.", "*versucht, %s mit einem trockenen Stoß der Schildkante zu unterbrechen.*" }, gruppe = { "Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Meine Antwort auf Magie hat einen Holzgriff.", "*rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" } },
    TAUNT = { name = "Spott", ziel = { "%s, schaut mich an, nicht die Schwächeren!", "*stellt sich breitbeinig vor %s und schlägt einladend auf den Schild.*" }, gruppe = { "Hier drüben! Der Ärger hat heute meinen Namen.", "*klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Die anderen haben Wichtigeres zu tun. Ich nicht.", "*tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" } },
    BATTLE_SHOUT = { name = "Schlachtruf", ziel = {  }, gruppe = { "Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" } },
    DEMORALIZING_SHOUT = { name = "Demoralisierender Ruf", ziel = {  }, gruppe = { "Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*zeigt mit der Klinge auf die wankende feindliche Linie.*" } },
    REVENGE = { name = "Rache", ziel = { "%s, Euer eigener Schwung arbeitet jetzt für mich.", "*fängt den Schlag von %s ab und beantwortet ihn ohne Zögern.*" }, gruppe = { "Danke für die Gelegenheit. Die kommt sofort zurück.", "*lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Ich vergesse Gesichter. Schläge nicht.", "*dreht sich aus der Abwehr direkt in den Gegenangriff.*" } },
    OVERPOWER = { name = "Überwältigen", ziel = { "%s, ich nehme Eure Einladung an.", "*weicht %s nur eine Handbreit aus und stößt sofort vor.*" }, gruppe = { "Da war eine Lücke. Ihr habt sie mir geschenkt.", "*gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Wer danebenhaut, lädt mich ein.", "*nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" } },
    MORTAL_STRIKE = { name = "Tödlicher Stoß", ziel = { "%s, dies ist der Augenblick, den Ihr übersehen habt.", "*lässt die schwere Waffe mit konzentrierter Wucht auf %s zufahren.*" }, gruppe = { "Ich spare mir den zweiten Versuch.", "*nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Manche Duelle enden mit einem Satz. Dieses nicht.", "*schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" } },
    WHIRLWIND = { name = "Wirbelwind", ziel = {  }, gruppe = { "Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Ich teile gern. Heute Stahl.", "*lässt die Klinge in weitem Schwung ringsum singen.*" } },
    BLOODTHIRST = { name = "Blutdurst", ziel = { "%s, jetzt wird es ein wenig ungemütlich.", "*geht mit einem schnellen Schritt auf %s los, ohne die Deckung aufzugeben.*" }, gruppe = { "Der Puls wird schneller. Die Hand bleibt ruhig.", "*atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" } },
    INTERCEPT = { name = "Abfangen", ziel = { "%s, Abkürzungen sind meine Spezialität.", "*schneidet %s mit einem überraschenden Sprint den Weg ab.*" }, gruppe = { "Ein Vorsprung ist nur geliehene Zeit.", "*stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" } },
    PUMMEL = { name = "Zuschlagen", ziel = { "%s, das nächste Wort bleibt bei Euch.", "*fährt %s mitten in die Ausholbewegung und bricht den Rhythmus.*" }, gruppe = { "Zu viele Worte. Zu wenig Deckung.", "*stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Wolltet Ihr noch etwas sagen? Nein? Gut.", "*bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" } },
    SWEEPING_STRIKES = { name = "Weitreichende Stöße", ziel = {  }, gruppe = { "Wenn schon Arbeit, dann richtig.", "*lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Mehrere Gegner? Spart Wege.", "*nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" } },
    DEATH_WISH = { name = "Todeswunsch", ziel = {  }, gruppe = { "Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" } },
    RECKLESSNESS = { name = "Tollkühnheit", ziel = {  }, gruppe = { "Vorsicht war gestern. Heute wird gehandelt.", "*verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*setzt den ganzen Körper in eine wilde Folge von Angriffen.*" } },
    LAST_STAND = { name = "Letztes Gefecht", ziel = {  }, gruppe = { "Bis hierher und keinen Schritt weiter.", "*stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Ich stehe noch. Das muss als Antwort genügen.", "*stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" } },
    SHIELD_WALL = { name = "Schildwall", ziel = {  }, gruppe = { "Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Wer durch mich hindurch will, braucht einen langen Atem.", "*schließt die letzte Lücke zwischen Schild und Rüstung.*" } },
    RETALIATION = { name = "Gegenschlag", ziel = {  }, gruppe = { "Wer austeilt, muss das Echo mögen.", "*öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" } },
    MOCKING_BLOW = { name = "Spöttischer Schlag", ziel = { "%s, zeigt mir doch endlich, was Ihr könnt!", "*täuscht bei %s eine schlechte Deckung an und lacht provozierend.*" }, gruppe = { "Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" } },
    BERSERKER_RAGE = { name = "Berserkerwut", ziel = {  }, gruppe = { "Angst? Die hat heute keinen Platz in meinem Kopf.", "*schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" } },
    BLOODRAGE = { name = "Blutrausch", ziel = {  }, gruppe = { "Schmerz ist eine Nachricht. Ich antworte später.", "*schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" } },
    DISARM = { name = "Entwaffnen", ziel = { "%s, Eure Hände wären ohne Stahl viel ungefährlicher.", "*versucht, den Waffenarm von %s mit einem kurzen, präzisen Hebel zu verdrehen.*" }, gruppe = { "Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" } },
    INTIMIDATING_SHOUT = { name = "Drohruf", ziel = {  }, gruppe = { "Lauft, solange Ihr noch wisst, wohin!", "*schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*schlägt donnernd gegen den Schild und bleckt die Zähne.*" } },
    CHALLENGING_SHOUT = { name = "Herausforderungsruf", ziel = {  }, gruppe = { "ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*schlägt mehrmals auf den Schild und brüllt die Gegner an.*" } },
    SLAM = { name = "Zerschmettern", ziel = { "%s, haltet gut fest, was Ihr noch festhalten wollt.", "*bringt die Waffe gegen %s in einen schweren, kontrollierten Abwärtshieb.*" }, gruppe = { "Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Lieber ein sauberer Treffer als fünf halbe.", "*lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" } },
    DEVASTATE = { name = "Verwüsten", ziel = { "%s, da fehlt bereits ein Stück Schutz.", "*setzt bei %s an derselben geschwächten Rüstungskante erneut nach.*" }, gruppe = { "Schon locker? Dann lösen wir den Rest auch noch.", "*schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" } },
    SHIELD_SLAM = { name = "Schildschlag", ziel = { "%s, schaut nicht nur auf mein Schwert.", "*rammt den Schild im richtigen Augenblick gegen %s.*" }, gruppe = { "Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Wer sagt, Verteidigung sei höflich?", "*macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" } },
    CONCUSSION_BLOW = { name = "Erschütternder Schlag", ziel = { "%s, ich nehme Euch kurz die Eile.", "*versucht, %s mit einem knappen, erschütternden Schlag zu treffen.*" }, gruppe = { "Ich versuche, Euch aus dem Takt zu bringen.", "*versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*verkürzt den Griff und schwingt mit überraschender Wucht.*" } },
    VICTORY_RUSH = { name = "Siegesrausch", ziel = { "%s, ich habe gerade erst angefangen.", "*nimmt %s nach einem kurzen triumphierenden Atemzug ins Visier.*" }, gruppe = { "Einer weniger. Die anderen stehen noch.", "*nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Feiern können wir später. Da bewegt sich noch etwas.", "*klopft sich einmal auf die Brust und setzt sofort nach.*" } },
    BATTLE_STANCE = { name = "Kampfhaltung", ziel = {  }, gruppe = { "Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" } },
    DEFENSIVE_STANCE = { name = "Verteidigungshaltung", ziel = {  }, gruppe = { "Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Heute gewinnt nicht, wer am lautesten brüllt.", "*senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" } },
    BERSERKER_STANCE = { name = "Berserkerhaltung", ziel = {  }, gruppe = { "Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Die Welt wird plötzlich sehr einfach: vorwärts.", "*lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" } },
    PIERCING_HOWL = { name = "Durchdringendes Heulen", ziel = {  }, gruppe = { "Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Nein, das war kein Wolfsrudel. Nur ich.", "*wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" } },
    SPEARING_STRIKE = { name = "Aufspießender Stoß", ziel = { "%s, zwischen Euren Platten ist noch Platz.", "*setzt die Waffenspitze präzise gegen eine Öffnung in der Deckung von %s.*" }, gruppe = { "Die Lücke ist schmal. Meine Spitze nicht.", "*führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Rüstung ist stark. Winkel sind stärker.", "*dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" } },
    TACTICAL_MASTERY = { name = "Taktiker", ziel = {  }, gruppe = { "Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*verändert unmerklich den Stand und bewahrt die Übersicht.*", "Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" } },
}
